import numpy as np
def basis(w):
    cols=[np.ones_like(t),x,v,x**2,x**3,v**2,v**3,x*v,x*x*v,x*v*v,np.abs(v)*v,np.cos(w*t),np.sin(w*t)]
    return np.column_stack(cols)
best=None
for w in np.arange(0.05,3.0,0.0025):
    X=basis(w)
    b=np.linalg.lstsq(X,dv_dt,rcond=None)[0]
    r=dv_dt-X@b
    e=np.mean(r**2)/np.var(dv_dt)
    if best is None or e<best[0]: best=(e,w,b)
